function send_refund( $type = 'refund.processed', $refund_id = 'rfnd_test123', $payment_id = 'pay_test123', $amount = 300, $order_id = 'order_test123' ) { $body = json_encode( array( 'id' => 'evt_' . str_replace( 'rfnd_', '', $refund_id ) . '_' . str_replace( '.', '_', $type ), 'event' => $type, 'payload' => array( 'refund' => array( 'entity' => array( 'id' => $refund_id, 'amount' => $amount, 'currency' => 'INR', 'payment_id' => $payment_id, 'status' => 'processed' ) ), 'payment' => array( 'entity' => array( 'id' => $payment_id, 'order_id' => $order_id ) ) ) ) ); return ( new CH_Payment_Controller( new Auth() ) )->receive_webhook( new Request( $body, array( 'x-razorpay-signature' => hash_hmac( 'sha256', $body, 'synthetic-webhook-secret' ) ) ) ); }

